import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse(`{"title":"Remove Coupon","description":"","frontmatter":{"outline":false,"examples":[{"id":"remove-coupon","title":"Remove Coupon from Cart","description":"Remove a discount coupon code from the shopping cart.","request":"POST /api/shop/remove-coupon\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 506,\\n  \\"cartToken\\": \\"62f2b3f5-a455-4c78-93ba-eabca63d32ec\\",\\n  \\"itemsCount\\": 1,\\n  \\"subtotal\\": 367.50,\\n  \\"discountAmount\\": 0,\\n  \\"taxAmount\\": 0,\\n  \\"shippingAmount\\": 0,\\n  \\"grandTotal\\": 367.50,\\n  \\"formattedSubtotal\\": \\"$367.50\\",\\n  \\"formattedGrandTotal\\": \\"$367.50\\",\\n  \\"couponCode\\": null,\\n  \\"success\\": true,\\n  \\"message\\": \\"Coupon removed successfully\\"\\n}\\n","commonErrors":[{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/remove-coupon.md","filePath":"api/rest-api/shop/cart/remove-coupon.md"}`),n={name:"api/rest-api/shop/cart/remove-coupon.md"};function s(d,e,c,i,l,u){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="remove-coupon" tabindex="-1">Remove Coupon <a class="header-anchor" href="#remove-coupon" aria-label="Permalink to &quot;Remove Coupon&quot;">​</a></h1><p>Remove a discount coupon code from the shopping cart.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/remove-coupon</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The cart&#39;s own token as a Bearer token, or a logged-in customer&#39;s token.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>Send <code>{}</code>. The cart is identified by the token, and the coupon by whatever is currently on that cart — there is no code to name.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>201 Created</code> carrying the whole recalculated cart, the same object <a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> returns, with <code>couponCode</code> back to <code>null</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the call completed.</td></tr><tr><td><code>message</code></td><td>string</td><td><code>Coupon removed successfully</code>.</td></tr><tr><td><code>couponCode</code></td><td>string</td><td><code>null</code> after removal.</td></tr><tr><td><code>discountAmount</code> / <code>grandTotal</code></td><td>number</td><td>Recalculated without the discount.</td></tr></tbody></table><p>The call is idempotent — running it on a cart with no coupon still answers <code>201</code> with <code>success: true</code>, so it is safe to call before applying a new code.</p><h2 id="effects" tabindex="-1">Effects <a class="header-anchor" href="#effects" aria-label="Permalink to &quot;Effects&quot;">​</a></h2><ul><li>The discount is dropped and the totals are recalculated, including any shipping or tax that depended on the discounted subtotal.</li><li>Cart items are untouched.</li><li>A cart holds one coupon at a time, so applying a different code replaces the current one without needing this call first.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Remove&quot; next to an applied coupon</strong> — one call, then re-render from the returned cart.</li><li><strong>Reset before trying another code</strong> — optional, since <a href="/api/rest-api/shop/cart/apply-coupon.html">Apply Coupon</a> overwrites the existing one.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Re-render from the response</strong> — it is the full recalculated cart, so no follow-up fetch is needed.</li><li><strong>Do not guard the call behind &quot;is a coupon applied&quot;</strong> — it is safe on a coupon-less cart.</li><li><strong>Send the cart token</strong> — without a Bearer token the call fails with <code>401</code>, even though the body is empty.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/apply-coupon.html">Apply Coupon</a> — apply a discount code to the cart</li><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> — read the current items and recalculated totals</li></ul>',20)]))}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
